    ["Play interactive fiction: a Z-machine interpreter for Infocom and Inform stories (.z3 .z5 .z8 .zblorb), with autosave."] = { fr = "Jouez à des fictions interactives : un interpréteur Z-machine pour les histoires Infocom et Inform (.z3 .z5 .z8 .zblorb), avec sauvegarde automatique.", es = "Juega a ficción interactiva: un intérprete Z-machine para historias de Infocom e Inform (.z3 .z5 .z8 .zblorb), con guardado automático.", de = "Interaktive Fiktion spielen: ein Z-Machine-Interpreter für Infocom- und Inform-Geschichten (.z3 .z5 .z8 .zblorb), mit automatischem Speichern." },

