    ["No stories yet."] = { fr = "Pas encore d'histoire.", es = "Todavía no hay historias.", de = "Noch keine Geschichten." },
    ["Copy Z-code story files (.z3, .z5, .z8, .zblorb) into:\n%1\nand tap Refresh."] = { fr = "Copiez des fichiers d'histoires Z-code (.z3, .z5, .z8, .zblorb) dans :\n%1\npuis touchez Actualiser.", es = "Copie archivos de historias Z-code (.z3, .z5, .z8, .zblorb) en:\n%1\ny pulse Actualizar.", de = "Kopieren Sie Z-Code-Geschichten (.z3, .z5, .z8, .zblorb) nach:\n%1\nund tippen Sie auf Aktualisieren." },
    ["Thousands of free stories are waiting on IFDB (ifdb.org) and the IF Archive (ifarchive.org). French stories too: fiction-interactive.fr."] = { fr = "Des milliers d'histoires gratuites vous attendent sur IFDB (ifdb.org) et l'IF Archive (ifarchive.org). Et en français : fiction-interactive.fr.", es = "Miles de historias gratuitas esperan en IFDB (ifdb.org) y el IF Archive (ifarchive.org). También en francés: fiction-interactive.fr.", de = "Tausende kostenlose Geschichten gibt es auf IFDB (ifdb.org) und im IF Archive (ifarchive.org). Auch auf Französisch: fiction-interactive.fr." },
    ["Most Infocom classics and every Inform 6 game work. See Help in the menu for how to play."] = { fr = "La plupart des classiques d'Infocom et tous les jeux Inform 6 fonctionnent. Voir l'aide dans le menu pour savoir comment jouer.", es = "Funcionan la mayoría de los clásicos de Infocom y todos los juegos de Inform 6. Consulte la ayuda del menú para saber cómo jugar.", de = "Die meisten Infocom-Klassiker und alle Inform-6-Spiele laufen. Wie man spielt, steht in der Hilfe im Menü." },
